<?php
if(!defined('ABSPATH'))exit;
/** Owner-supplied query rows stay private and are never paired with pages by guesswork. */
function hsh_query_csv($csv){
    if(!is_string($csv)||strlen($csv)>2000000||strpos($csv,"\0")!==false||preg_match('//u',$csv)!==1)return new WP_Error('hsh_query_format','UTF-8のCSVを2MB以内で選んでください。');
    $f=fopen('php://temp','r+');fwrite($f,preg_replace('/^\xEF\xBB\xBF/','',$csv));rewind($f);
    try{$headers=fgetcsv($f,0,',','"','');if(!is_array($headers))return new WP_Error('hsh_query_header','検索キーワードのCSVを選んでください。');$cols=array();$aliases=array('query'=>array('上位のクエリ','最上位のクエリ','検索キーワード','Top queries','Query'),'clicks'=>array('クリック数','Clicks'),'impressions'=>array('表示回数','Impressions'),'position'=>array('掲載順位','平均掲載順位','Position'));
        foreach($aliases as $key=>$names)foreach($headers as $i=>$h)if(in_array(trim($h),$names,true)){$cols[$key]=$i;break;}if(count($cols)!==4)return new WP_Error('hsh_query_header','Search Consoleの検索キーワード（クエリ）のCSVを選んでください。');
        $rows=array();$seen=array();$count=0;while(($r=fgetcsv($f,0,',','"',''))!==false){if(count($r)===1&&($r[0]===null||$r[0]===''))continue;if(++$count>2000)return new WP_Error('hsh_query_limit','2000行以内で取り込んでください。');$q=trim($r[$cols['query']]??'');$c=hsh_gsc_number($r[$cols['clicks']]??'');$i=hsh_gsc_number($r[$cols['impressions']]??'');$p=hsh_gsc_number($r[$cols['position']]??'');if($q===''||strlen($q)>1000||isset($seen[$q])||$c===null||$i===null||$p===null||$c!==(float)(int)$c||$i!==(float)(int)$i||$c>$i||$p>1000||($i>0&&$p<1))return new WP_Error('hsh_query_row','重複や形式が不正な行があります。元のCSVを確認してください。');$seen[$q]=true;$priority=hsh_gsc_priority($c,$i,$p);$rows[]=array('query'=>sanitize_text_field($q),'clicks'=>(int)$c,'impressions'=>(int)$i,'position'=>$p,'action'=>$priority['action']);}
        if(!$rows)return new WP_Error('hsh_query_empty','検索キーワードがありません。');usort($rows,function($a,$b){return $b['impressions']<=>$a['impressions'];});return $rows;
    }finally{fclose($f);}
}
function hsh_growth_month($month){
    if(!is_string($month)||!preg_match('/^(20[0-9]{2})-(0[1-9]|1[0-2])$/D',$month))return new WP_Error('hsh_month','集計月を確認してください。');$counts=get_option('hsh_request_counts',array());$totals=array();$days=0;
    foreach((array)$counts as $day=>$rows)if(substr($day,0,7)===str_replace('-','_',$month)){++$days;foreach($rows as $slug=>$n)if(isset(hsh_growth_summaries()[$slug]))$totals[$slug]=($totals[$slug]??0)+max(0,(int)$n);}
    arsort($totals);return array('month'=>$month,'recorded_days'=>$days,'requests'=>$totals,'search_pages'=>get_option('hsh_gsc_pages',null),'search_queries'=>get_option('hsh_gsc_queries',null));
}
function hsh_growth_operations(){
    if(!current_user_can('manage_options'))return;$message='';
    if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){check_admin_referer('hsh_growth_ops');if(isset($_POST['clear_queries'])){delete_option('hsh_gsc_queries');$message='検索キーワードの控えを削除しました。';}elseif(isset($_FILES['query_csv'])){$f=$_FILES['query_csv'];if(!is_array($f)||($f['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK||!is_string($f['tmp_name']??null)||!is_int($f['size']??null)||$f['size']>2000000||!is_uploaded_file($f['tmp_name']))$message='2MB以内のCSVを選んでください。';else{$period=hsh_gsc_parse("Page,Clicks,Impressions,Position\n".home_url('/').",0,1,1\n",sanitize_text_field(wp_unslash($_POST['start']??'')),sanitize_text_field(wp_unslash($_POST['end']??'')));$rows=hsh_query_csv(file_get_contents($f['tmp_name']));if(is_wp_error($period)||is_wp_error($rows))$message=is_wp_error($period)?$period->get_error_message():$rows->get_error_message();else{$data=array('start'=>$period['start'],'end'=>$period['end'],'imported_at'=>time(),'rows'=>$rows);$message=update_option('hsh_gsc_queries',$data,false)?'検索キーワードを管理画面に保存しました。':'保存できませんでした。以前の記録は残っています。';}}}}
    echo '<div class="wrap"><h1>月ごとの振り返りと公開前の確認</h1>';if($message)echo '<div class="notice notice-info"><p>'.esc_html($message).'</p></div>';
    $month=isset($_GET['month'])&&is_string($_GET['month'])?wp_unslash($_GET['month']):wp_date('Y-m');$report=hsh_growth_month($month);echo '<form method="get"><input type="hidden" name="page" value="hsh-growth"><label>集計月 <input type="month" name="month" value="'.esc_attr(is_wp_error($report)?wp_date('Y-m'):$month).'"></label><button class="button">表示する</button></form>';
    if(!is_wp_error($report)){echo '<h2>'.esc_html($month).'の記録</h2><p>記録のある日：'.(int)$report['recorded_days'].'日。保存されている直近90日の到達件数の概数です。全13記事への計測拡大は'.esc_html(str_replace('_','/',(string)get_option('hsh_all_articles_counted_since',wp_date('Y_m_d')))).'から。それ以前は初回3記事のみです。正確なPV・訪問者数ではありません。</p><ul>';foreach($report['requests'] as $slug=>$n)echo '<li>'.esc_html($slug).'：'.(int)$n.'件</li>';echo '</ul>';if(!$report['requests'])echo '<p>この月の到達記録はありません。</p>';foreach(array('search_pages'=>'検索のページ別集計','search_queries'=>'検索キーワード集計') as $k=>$label){$d=$report[$k];echo '<p>'.esc_html($label).'：'.(is_array($d)?esc_html($d['start'].'〜'.$d['end']).'（月別到達集計とは期間が異なる場合があります）':'未取込').'</p>';}}
    echo '<h2>Search Consoleの検索キーワード</h2><p>検索パフォーマンスから「検索キーワード」のCSVを出力し、元の集計期間を指定してください。検索語と特定の記事の対応はこのCSVだけでは分かりません。Googleの画面でページも絞り込んでから修正を判断します。</p><form method="post" enctype="multipart/form-data">';wp_nonce_field('hsh_growth_ops');echo '<p><label>開始日 <input type="date" name="start" required></label> <label>終了日 <input type="date" name="end" required max="'.esc_attr(wp_date('Y-m-d')).'"></label></p><input type="file" name="query_csv" accept=".csv,text/csv" required><button class="button">取り込む</button></form>';
    $queries=get_option('hsh_gsc_queries',array());if(!empty($queries['rows'])){echo '<table class="widefat striped"><thead><tr><th>検索語</th><th>クリック</th><th>表示</th><th>平均順位</th><th>確認すること</th></tr></thead><tbody>';foreach($queries['rows'] as $r)echo '<tr><td>'.esc_html($r['query']).'</td><td>'.(int)$r['clicks'].'</td><td>'.(int)$r['impressions'].'</td><td>'.esc_html($r['position']).'</td><td>'.esc_html($r['action']).'</td></tr>';echo '</tbody></table><form method="post">';wp_nonce_field('hsh_growth_ops');echo '<button name="clear_queries" value="1" class="button">検索語の控えを削除</button></form>';}
    echo '<p><a href="'.esc_url(admin_url('themes.php?page=hsh-search-review')).'">ページ別の検索実績を取り込む</a></p><h2>公開前に確認すること</h2><ul><li>体験したこと、一般的な説明、未確認の情報を分ける。</li><li>商品名・仕様は公式資料と現物を照合し、URLと確認日を管理メモへ残す。</li><li>写真の撮影者・掲載許可・生成画像の表示を確認する。</li><li>位置情報、顔、住所、名札、反射に写った物を点検する。</li><li>記事と合う表紙、本文写真、代替説明を用意する。</li><li>広告がある場合は、広告表示と案件条件を確認する。</li><li>スマホの改行、表、リンク、検索向け説明文を確認する。</li><li>価格・仕様・法令などは次回の確認日を決める。</li></ul><p>記事・写真管理の「未確認のこと」「出典と確認日」「次回の確認日」に記録できます。画像の位置情報の削除と、写っている内容の点検は別の作業です。</p></div>';
}
add_action('admin_menu',function(){add_theme_page('月ごとの振り返り','月ごとの振り返り','manage_options','hsh-growth','hsh_growth_operations');});
